// State tracker for block parser (stack based set/reset semantics).
export class State {
    constructor() { this._stack = []; }
    set(state) { this._stack.push(state); }
    reset() { this._stack.pop(); }
    isstate(state) { return this._stack.length > 0 && this._stack[this._stack.length - 1] === state; }
}

// Priority-sorted registry of processors.
export class Registry {
    constructor() {
        this._data = {};
        this._priority = [];
        this._is_sorted = false;
    }
    register(item, name, priority) {
        this._data[name] = item;
        this._priority.push({ name, priority });
        this._is_sorted = false;
    }
    _sort() {
        this._priority.sort((a, b) => b.priority - a.priority);
        this._is_sorted = true;
    }
    get count() {
        if (!this._is_sorted) this._sort();
        return this._priority.length;
    }
    at(i) {
        if (!this._is_sorted) this._sort();
        return this._data[this._priority[i].name];
    }
    get(name) { return this._data[name]; }
    [Symbol.iterator]() {
        if (!this._is_sorted) this._sort();
        const self = this;
        let i = 0;
        return {
            next() {
                if (i < self._priority.length) {
                    return { value: self._data[self._priority[i++].name], done: false };
                }
                return { value: undefined, done: true };
            }
        };
    }
}

// Python-style expandtabs.
export function expandtabs(s, tabsize) {
    let result = '';
    let col = 0;
    for (const ch of s) {
        if (ch === '\t') {
            const n = tabsize - (col % tabsize);
            result += ' '.repeat(n);
            col += n;
        } else if (ch === '\n' || ch === '\r') {
            result += ch;
            col = 0;
        } else {
            result += ch;
            col += 1;
        }
    }
    return result;
}

