    insert(i, el) { this.children.splice(i, 0, el); }
    get(i) { return this.children[i]; }
    set(key, value) { this.attrib.set(key, String(value)); }
    getAttr(key, def = null) { return this.attrib.has(key) ? this.attrib.get(key) : def; }
